 static android.widget.Button find(android.view.View v){if(v instanceof android.widget.Button&&((android.widget.Button)v).getText().toString().equals("Enviar"))return (android.widget.Button)v;if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++){android.widget.Button b=find(g.getChildAt(i));if(b!=null)return b;}}return null;}
 @Override public void onStart(){Bundle out=new Bundle();try{runOnMainSync(new Runnable(){public void run(){}});Context c=getTargetContext();DurableCode.awaitReady();check(c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionCode==590001,"updated normal APK");check(JavaAlgorithm.kind().equals("pipeline")&&JavaAlgorithm.process("3,1,3,-2").equals("2"),"full Java program after cold start");Class<?> proof=Class.forName("com.bananalab.lite.GeneralProof");java.lang.reflect.Method value=proof.getDeclaredMethod("value"),marker=proof.getDeclaredMethod("marker");value.setAccessible(true);marker.setAccessible(true);check(value.invoke(null).equals(28)&&marker.invoke(null).equals("general-v2"),"general Java source installed in APK");check(KnowledgeNotebook.retrieve(KnowledgeNotebook.data(c),"como se llama el motor secreto de Banana").contains("Nucleo Naranja"),"knowledge restored across normal APK/fresh state");check(KnowledgeNotebook.retrieve(KnowledgeNotebook.data(c),"como se llama la biblioteca de animaciones de Banana").contains("Coreografia Azul"),"external provenance restored");JSONObject meta=ModelDepot.embedded(c).getJSONObject("models");check(meta.getJSONObject("chat").getJSONObject("report").getBoolean("accepted")&&meta.getJSONObject("pixel").getJSONObject("report").getBoolean("accepted"),"trained weights embedded");for(String kind:new String[]{"chat","pixel"})try(InputStream in=c.getAssets().open(ModelDepot.asset(kind))){byte[] bytes=OnDeviceJava.bytes(in,8000000);check(CoreBuild.sha(bytes).equals(meta.getJSONObject(kind).getString("sha256")),"model asset matches checkpoint hash");}check(meta.getJSONObject("pixel").getJSONObject("report").getInt("trainedLayers")==4,"all-layer checkpoint survives rebuild");check(meta.getJSONObject("chat").getJSONObject("report").getBoolean("fullTransformer"),"full Chat checkpoint restored");check(ModelDepot.tuned(c,"pixel")&&ModelDepot.preview(c,"pixel").length()==1024,"trained renderer survives new APK and fresh install");BananaTransformer chat=TransformerBrain.load(c);check(chat.vocabSize==542,"chat binary loaded");if(phase.equals("upgrade")){check(JavaProject.working(c).length()==0,"source synchronization after full build");String name=c.getSharedPreferences("stage56",0).getString("fito","");BananaEngine.Result kiss=BananaEngine.run(c,"Fito besa a Bani",new ArrayList<String[]>(),"",true,OwnBrain.load(c));check(kiss.changed&&kiss.scene.get(name).designId.equals(c.getSharedPreferences("stage56",0).getString("design","")),"scene identities retained");}else check(!ApkSigning.prefs(c).contains("sealed"),"private signing key not in APK");final Activity screen=startActivitySync(new android.content.Intent(c,BananaActivity.class).addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK));runOnMainSync(new Runnable(){public void run(){android.widget.Button button=find(screen.getWindow().getDecorView());check(button!=null&&button.getTypeface().equals(android.graphics.Typeface.create("sans-serif-medium",button.getTypeface().getStyle())),"actual chosen font visible on Enviar");final android.app.AlertDialog fontDialog=UiTypeface.show(new android.app.AlertDialog.Builder(screen).setTitle("Prueba de fuente").setMessage("Texto de prueba").setPositiveButton("Cerrar",null));android.widget.TextView dialogText=(android.widget.TextView)fontDialog.findViewById(android.R.id.message);check(dialogText!=null&&dialogText.getTypeface().equals(android.graphics.Typeface.create("sans-serif-medium",dialogText.getTypeface().getStyle())),"font applied to dialog text");fontDialog.dismiss();check(button!=null&&button.getBackgroundTintList()!=null&&button.getBackgroundTintList().getDefaultColor()==0xff962a32,"actual Enviar button red on screen");screen.finish();}});out.putString("stream","PASS STAGE56_REOPEN "+phase+" full-DX app starts, coordinated program works, trained model assets/hash/preview restored, data retained.\n");finish(Activity.RESULT_OK,out);}catch(Throwable e){StringWriter s=new StringWriter();e.printStackTrace(new PrintWriter(s));out.putString("stream","FAIL "+s);finish(Activity.RESULT_CANCELED,out);}}
